import{_ as t,o,c as r,ag as a}from"./chunks/framework.8tqBsFWt.js";const _=JSON.parse('{"title":"Project Tools","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools/projects.md","filePath":"reference/tools/projects.md"}'),d={name:"reference/tools/projects.md"};function n(c,e,s,i,l,p){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="project-tools" tabindex="-1">Project Tools <a class="header-anchor" href="#project-tools" aria-label="Permalink to &quot;Project Tools&quot;">​</a></h1><hr><h2 id="create_project" tabindex="-1">create_project <a class="header-anchor" href="#create_project" aria-label="Permalink to &quot;create_project {#create_project}&quot;">​</a></h2><p>Create a new project. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>02. Projects</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td>Unique project name</td></tr><tr><td><code>project_type</code></td><td>✅</td><td><code>&quot;Retainer&quot;</code> | <code>&quot;T&amp;M&quot;</code> | <code>&quot;Fixed Price&quot;</code> | <code>&quot;Pro Bono&quot;</code> | <code>&quot;Agile&quot;</code> | <code>&quot;Internal&quot;</code> — never defaulted</td></tr><tr><td><code>client_name</code></td><td>Cond.</td><td>Client org — created automatically if new. <strong>Omit for Internal projects</strong> — VERA assigns the implicit &quot;Internal&quot; client automatically</td></tr><tr><td><code>contract_value</code></td><td>Cond.</td><td>Required for Fixed Price</td></tr><tr><td><code>hours_budget</code></td><td>Cond.</td><td>Required for Retainer (annual hours). Optional for others.</td></tr><tr><td><code>billing_rate</code></td><td></td><td>Hourly rate billed to client</td></tr><tr><td><code>deadline</code></td><td></td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>notes</code></td><td></td><td></td></tr><tr><td><code>project_category</code></td><td></td><td>Defaults to <code>&quot;client&quot;</code></td></tr></tbody></table><p><strong>Rules:</strong></p><ul><li>Never assume a default project type — always ask</li><li><code>client_name</code> is not required for Internal projects — the Internal client is implicit</li><li><strong>Fixed Price requires a positive <code>contract_value</code></strong> — the endpoint rejects creation with <code>❌ contract_value is required for Fixed Price projects</code> if it&#39;s missing or ≤ 0. Fixed Price revenue is <code>% complete × contract_value</code>, so without it the project would recognize $0 revenue forever.</li><li>For Agile parents: no contract_value or hours_budget on the parent itself</li><li>After Agile parent creation, offer to set up Sprint 1</li><li>&quot;Create a retainer&quot; means <code>create_project</code> with <code>project_type=&quot;Retainer&quot;</code> — this tool creates the parent engagement. The first period child is auto-created by <code>create_project</code>. Use <code>create_retainer_period</code> only when adding a <strong>new period to an existing retainer parent</strong> (e.g. &quot;create the June period for Acme Retainer&quot;).</li><li>On creation, the <strong>Project Management</strong> task is automatically enabled on the new project so it starts with at least one enabled task — you can allocate hours immediately, and use <strong>Edit tasks</strong> to add more (Design, Development, etc.). If the tenant has archived or renamed its Project Management task, the project is simply created with no default task (no error).</li></ul><hr><hr><h2 id="rename_project" tabindex="-1">rename_project <a class="header-anchor" href="#rename_project" aria-label="Permalink to &quot;rename_project {#rename_project}&quot;">​</a></h2><p>Rename a project and update all references. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>02. Projects</code>, <code>01. Time Entries</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>old_name</code></td><td>✅</td><td></td></tr><tr><td><code>new_name</code></td><td>✅</td><td></td></tr></tbody></table><p><strong>Protected projects:</strong> the internal time-off projects PTO, Sick, and Leave can be neither renamed nor cancelled (<code>cancel_project</code> carries the same guard) — both return a 403 (&quot;…is a protected time-off project and cannot be renamed/cancelled&quot;) to keep time-off logging intact. Other internal/overhead projects are unaffected.</p><hr><h2 id="update_project" tabindex="-1">update_project <a class="header-anchor" href="#update_project" aria-label="Permalink to &quot;update_project {#update_project}&quot;">​</a></h2><p>Update one or more fields on an existing project. <strong>Owner or Manager.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>02. Projects</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td>Current project name</td></tr><tr><td><code>new_name</code></td><td></td><td>Rename the project</td></tr><tr><td><code>status</code></td><td></td><td><code>active</code> | <code>completed</code> | <code>cancelled</code></td></tr><tr><td><code>is_billable</code></td><td></td><td>Boolean</td></tr><tr><td><code>alert_threshold</code></td><td></td><td>% at which to flag the budget (default 80)</td></tr><tr><td><code>notes</code></td><td></td><td>Free-text notes</td></tr><tr><td><code>deadline</code></td><td></td><td><code>YYYY-MM-DD</code></td></tr><tr><td><code>contract_value</code></td><td></td><td><strong>Owner only.</strong> Setting this as a Manager returns <code>❌ Failed: Only owners can change a project&#39;s contract_value…</code></td></tr><tr><td><code>billing_rate</code></td><td></td><td><strong>Owner only.</strong> Same gate as <code>contract_value</code>.</td></tr><tr><td><code>hours_budget</code></td><td></td><td><strong>Owner only.</strong> Same gate as <code>contract_value</code>.</td></tr></tbody></table><p><strong>Role notes:</strong></p><ul><li>Managers can set <code>new_name</code>, <code>status</code>, <code>is_billable</code>, <code>alert_threshold</code>, <code>notes</code>, and <code>deadline</code>.</li><li><code>contract_value</code>, <code>billing_rate</code>, and <code>hours_budget</code> are <strong>owner-only on write</strong>, mirroring the read-side isolation in <code>get_project_info</code>. A manager attempting to set any of these gets a 403.</li></ul><p><strong>Deterministic routing (updated #1090):</strong> Field-bearing phrasings now route to <code>update_project</code> in the extractor instead of being hijacked by <code>edit_entry</code> or <code>set_rate</code>. The extractor has an <code>update_project</code> entry with <code>object_nouns: [&#39;contract value&#39;, &#39;billing rate&#39;, &#39;status&#39;, &#39;notes&#39;, &#39;billable&#39;, &#39;is billable&#39;]</code>.</p><p><strong>Deterministic owner execution (updated #1091):</strong> <code>contract_value</code>, <code>billing_rate</code>, and <code>hours_budget</code> now execute via DET confirm→fire gates (no model turn). Both colon form (<code>&quot;update CityCore App Development: contract value 130000&quot;</code>) and preposition form (<code>&quot;set the contract value for CityCore App Development to 130000&quot;</code>) resolve the project and present a clean confirm. Owner-only denial is also deterministic. Missing-value inputs fall through to the model.</p><hr><h2 id="list_projects" tabindex="-1">list_projects <a class="header-anchor" href="#list_projects" aria-label="Permalink to &quot;list_projects {#list_projects}&quot;">​</a></h2><p>List all projects (filtered by role).</p><p><strong>Reads from</strong>: <code>02. Projects</code>, <code>04. Clients</code>, <code>03. Users</code></p><p><strong>Returns</strong>: name, <code>client_name</code> (resolved from <code>client_id</code>; <code>null</code> when the project has no client, including when <code>client_id</code> points at a client that no longer resolves), type, pm_name, status, deadline (Owner/Manager only)</p><hr><h2 id="get_project_info" tabindex="-1">get_project_info <a class="header-anchor" href="#get_project_info" aria-label="Permalink to &quot;get_project_info {#get_project_info}&quot;">​</a></h2><p>Full project details. Always call this first when checking project status — it tells you the type, which determines whether to follow up with <code>get_project_status</code> or <code>get_retainer_status</code>.</p><p><strong>Reads from</strong>: <code>02. Projects</code>, <code>04. Clients</code>, <code>03. Users</code></p><p><strong>Returns</strong>: name, client, type, budget_hours, status, pm_name, deadline (Owner/Manager), contract_value (Owner), billing_rate (Owner)</p><hr><h2 id="get_project_status" tabindex="-1">get_project_status <a class="header-anchor" href="#get_project_status" aria-label="Permalink to &quot;get_project_status {#get_project_status}&quot;">​</a></h2><p>Task-level budget status for <strong>non-retainer</strong> projects.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>06. Project_Tasks</code>, <code>02. Projects</code></p><p><strong>Returns per task</strong>: hours_logged, budget_hours, % used, alert status, committed hours (logged + allocated)</p><p><strong>Do not use for retainers</strong> — use <code>get_retainer_status</code> instead.</p><hr><h2 id="get_project_health" tabindex="-1">get_project_health <a class="header-anchor" href="#get_project_health" aria-label="Permalink to &quot;get_project_health {#get_project_health}&quot;">​</a></h2><p>Burn rate health for <strong>retainer</strong> projects, with envelope-aware forecast.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>02. Projects</code>, <code>07. Budgets</code></p><p><strong>Returns</strong>: hours_logged, days_elapsed, pace_per_day, projected_eom_hours, allocated_remaining, forecast_with_allocations, variance, utilization%, status</p><p><strong>Status values</strong>: <code>critical_overpace</code>, <code>warning_overpace</code>, <code>on_track</code>, <code>warning_underpace</code>, <code>critical_underpace</code></p><hr><h2 id="get_my_projects" tabindex="-1">get_my_projects <a class="header-anchor" href="#get_my_projects" aria-label="Permalink to &quot;get_my_projects {#get_my_projects}&quot;">​</a></h2><p>Projects where the requesting user is the PM (or all projects if Owner).</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code></p><hr><h2 id="delete_project" tabindex="-1">delete_project <a class="header-anchor" href="#delete_project" aria-label="Permalink to &quot;delete_project {#delete_project}&quot;">​</a></h2><p>Permanently hard-delete a project. <strong>Owner only.</strong> Only allowed when the project is completely empty: no time entries, no allocation envelopes (any status), no vendor liabilities, and no period/sprint children. Use <code>cancel_project</code> for anything with history.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>02. Projects</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td></td><td>Name of the project</td></tr><tr><td><code>project_id</code></td><td></td><td>ID of the project (alternative to name)</td></tr></tbody></table><blockquote><p>Returns 400 if the project has time entries, budgets (any status), liabilities, or child periods/sprints — with a message pointing to <code>cancel_project</code> as the correct affordance. The protected time-off projects (PTO, Sick, Leave) return 403. This action is irreversible.</p></blockquote><p><strong>Returns</strong>: <code>project_id</code>, <code>name</code>, <code>message</code></p><hr><h2 id="close_project" tabindex="-1">close_project <a class="header-anchor" href="#close_project" aria-label="Permalink to &quot;close_project {#close_project}&quot;">​</a></h2><p>Mark a project (and any active or planned period/sprint children) <code>completed</code>. <strong>Owner only.</strong> Use this for projects that finished successfully — for projects that won&#39;t be completed, use <code>cancel_project</code> instead.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>02. Projects</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td></td><td>Name of the project</td></tr><tr><td><code>project_id</code></td><td></td><td>ID of the project (alternative to name)</td></tr></tbody></table><blockquote><p>Rejects a period/sprint child directly — close the parent project instead. Also resolves any open retainer/sprint renewal Unresolved Items for the project.</p></blockquote><p><strong>Returns</strong>: <code>project_id</code>, <code>project_name</code>, <code>closed_count</code>, <code>message</code></p><hr><h2 id="cancel_project" tabindex="-1">cancel_project <a class="header-anchor" href="#cancel_project" aria-label="Permalink to &quot;cancel_project {#cancel_project}&quot;">​</a></h2><p>Mark a project (and any active or planned period/sprint children) <code>cancelled</code>, hiding it from <code>list_projects</code>. <strong>Owner only.</strong> Use this for projects that will not be completed — for projects that finished successfully, use <code>close_project</code> instead.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>02. Projects</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td></td><td>Name of the project</td></tr><tr><td><code>project_id</code></td><td></td><td>ID of the project (alternative to name)</td></tr></tbody></table><blockquote><p>Rejects a period/sprint child directly — cancel the parent project instead. Rejects a project already cancelled. The protected time-off projects (PTO, Sick, Leave) return 403 (see <code>rename_project</code> above). Also resolves any open retainer/sprint renewal Unresolved Items for the project.</p></blockquote><p><strong>Returns</strong>: <code>project_id</code>, <code>project_name</code>, <code>cancelled_count</code>, <code>message</code></p><hr><h2 id="set_project_budget" tabindex="-1">set_project_budget <a class="header-anchor" href="#set_project_budget" aria-label="Permalink to &quot;set_project_budget {#set_project_budget}&quot;">​</a></h2><p>Set the project-level hours budget (Tier 1). <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>02. Projects</code> col D</p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td></td></tr><tr><td><code>budget_hours</code></td><td>✅</td><td>Total hours cap</td></tr></tbody></table><hr><h2 id="set_project_deadline" tabindex="-1">set_project_deadline <a class="header-anchor" href="#set_project_deadline" aria-label="Permalink to &quot;set_project_deadline {#set_project_deadline}&quot;">​</a></h2><p>Set the project delivery date. <strong>Owner or PM of the project</strong> (Managers who are not the PM get a deterministic denial).</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>02. Projects</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>project_name</code></td><td>✅</td><td></td></tr><tr><td><code>deadline</code></td><td>✅</td><td><code>YYYY-MM-DD</code></td></tr></tbody></table><p><strong>Deterministic routing:</strong> natural-language date inputs (&quot;set the deadline for X to next Friday&quot;) resolve the date and show a confirm with the concrete ISO date before writing — no model round-trip. A non-PM manager gets a deterministic denial: <code>❌ Failed: Only owners or &lt;project&gt;&#39;s PM can set its deadline.</code> ISO date inputs (&quot;set the deadline for X to 2027-01-16&quot;) fall through to the model.</p><hr><h2 id="list_tasks" tabindex="-1">list_tasks <a class="header-anchor" href="#list_tasks" aria-label="Permalink to &quot;list_tasks {#list_tasks}&quot;">​</a></h2><p>All task types with billability flag.</p><p>Shared with <a href="/reference/tools/tasks.html#list_tasks">Task Tools</a> — documented there.</p><hr><h2 id="create_task" tabindex="-1">create_task <a class="header-anchor" href="#create_task" aria-label="Permalink to &quot;create_task {#create_task}&quot;">​</a></h2><p>Create a new global task type. <strong>Owner only.</strong></p><p>Shared with <a href="/reference/tools/tasks.html#create_task">Task Tools</a> — documented there.</p><hr><h2 id="rename_task" tabindex="-1">rename_task <a class="header-anchor" href="#rename_task" aria-label="Permalink to &quot;rename_task {#rename_task}&quot;">​</a></h2><p>Rename a task type globally. <strong>Owner only.</strong></p><p>Shared with <a href="/reference/tools/tasks.html#rename_task">Task Tools</a> — documented there.</p><hr><h2 id="archive_task" tabindex="-1">archive_task <a class="header-anchor" href="#archive_task" aria-label="Permalink to &quot;archive_task {#archive_task}&quot;">​</a></h2><p>Archive a task type so it no longer appears in menus or as a write target. <strong>Owner only.</strong></p><p>Shared with <a href="/reference/tools/tasks.html#archive_task">Task Tools</a> — documented there.</p><hr><h2 id="unarchive_task" tabindex="-1">unarchive_task <a class="header-anchor" href="#unarchive_task" aria-label="Permalink to &quot;unarchive_task {#unarchive_task}&quot;">​</a></h2><p>Restore an archived task so it appears in menus again. <strong>Owner only.</strong></p><p>Shared with <a href="/reference/tools/tasks.html#unarchive_task">Task Tools</a> — documented there.</p><hr><h2 id="get_project_tasks" tabindex="-1">get_project_tasks <a class="header-anchor" href="#get_project_tasks" aria-label="Permalink to &quot;get_project_tasks {#get_project_tasks}&quot;">​</a></h2><p>All enabled tasks for a project, with budget and hours logged.</p><p><strong>Reads from</strong>: <code>06. Project_Tasks</code>, <code>05. Tasks</code>, <code>01. Time Entries</code></p><p><strong>Returns per task</strong>: task_name, is_billable, budget_hours, alert_threshold, hours_logged, % used, budget_summary</p><p><strong>budget_summary includes:</strong></p><ul><li><code>tasks_without_budget</code>: count of enabled tasks with no budget set</li><li><code>over_project_budget</code>: whether task totals exceed the project budget</li><li><code>unallocated_hours</code>: project budget minus sum of task budgets</li></ul><hr><h2 id="enable_task_for_project" tabindex="-1">enable_task_for_project <a class="header-anchor" href="#enable_task_for_project" aria-label="Permalink to &quot;enable_task_for_project {#enable_task_for_project}&quot;">​</a></h2><p>Enable a task on a project with optional budget. <strong>Owner or project PM.</strong></p><p>Shared with <a href="/reference/tools/tasks.html#enable_task_for_project">Task Tools</a> — documented there.</p><hr><h2 id="disable_task_for_project" tabindex="-1">disable_task_for_project <a class="header-anchor" href="#disable_task_for_project" aria-label="Permalink to &quot;disable_task_for_project {#disable_task_for_project}&quot;">​</a></h2><p>Disable a task on a project. <strong>Owner or project PM.</strong></p><p>Shared with <a href="/reference/tools/tasks.html#disable_task_for_project">Task Tools</a> — documented there.</p><hr><h2 id="get_retainer_status" tabindex="-1">get_retainer_status <a class="header-anchor" href="#get_retainer_status" aria-label="Permalink to &quot;get_retainer_status {#get_retainer_status}&quot;">​</a></h2><p>Monthly burn rate for a retainer project. See <a href="/reference/concepts/retainers.html">Retainers</a> for interpretation guide.</p><p><strong>Reads from</strong>: <code>01. Time Entries</code>, <code>02. Projects</code>, <code>07. Budgets</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code></p><p><strong>Returns</strong>: budget_hours, hours_logged, hours_remaining, days_elapsed, days_remaining, pace_per_day, projected_eom_hours, allocated_remaining, forecast_with_allocations, variance, utilization_percent, exceed_date, unused_hours, unused_value, status</p><hr><h2 id="get_retainer_periods" tabindex="-1">get_retainer_periods <a class="header-anchor" href="#get_retainer_periods" aria-label="Permalink to &quot;get_retainer_periods {#get_retainer_periods}&quot;">​</a></h2><p>Full period history for a Retainer parent — past, current, and future periods with hours logged, budget, burn %, and (Owner only) contract value per period. <strong>Manager/Owner.</strong></p><p><strong>Reads from</strong>: <code>02. Projects</code>, <code>01. Time Entries</code></p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>project_name</code> or <code>project_id</code></p><p><strong>Returns</strong>: <code>parent_project</code>, <code>period_count</code>, <code>total_hours_budget</code>, <code>total_hours_logged</code>, <code>total_contract_value</code> (Owner), and <code>periods[]</code> — each with <code>period_id</code>, <code>period_name</code>, <code>period_number</code>, <code>period_status</code>, <code>period_start</code>, <code>period_end</code>, <code>hours_budget</code>, <code>hours_logged</code>, <code>hours_remaining</code>, <code>burn_pct</code>, <code>contract_value</code> (Owner)</p><hr><h2 id="get_pm_retainer_summary" tabindex="-1">get_pm_retainer_summary <a class="header-anchor" href="#get_pm_retainer_summary" aria-label="Permalink to &quot;get_pm_retainer_summary {#get_pm_retainer_summary}&quot;">​</a></h2><p>All retainer projects assigned to a PM, with burn status for each. <strong>Manager/Owner.</strong></p><hr><h2 id="create_retainer_period" tabindex="-1">create_retainer_period <a class="header-anchor" href="#create_retainer_period" aria-label="Permalink to &quot;create_retainer_period {#create_retainer_period}&quot;">​</a></h2><p>Add a new billing period to an existing Retainer parent. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>02. Projects</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>parent_project_name</code></td><td>✅</td><td>The Retainer parent (must already exist — use <code>create_project</code> for the first period)</td></tr><tr><td><code>period_start</code></td><td>✅</td><td>First day of the billing month, <code>YYYY-MM-01</code></td></tr><tr><td><code>hours_budget</code></td><td></td><td>Overrides the inherited value from the most recent period</td></tr><tr><td><code>contract_value</code></td><td></td><td>Overrides the inherited value from the most recent period</td></tr><tr><td><code>billing_rate</code></td><td></td><td>Overrides the inherited value from the most recent period</td></tr><tr><td><code>confirmed</code></td><td></td><td>Omit (or <code>false</code>) to preview the inherited terms; pass <code>true</code> to actually create the period</td></tr></tbody></table><p>Period number auto-increments; financial terms not explicitly overridden are inherited from the most recent period (or the parent&#39;s own defaults, for the very first period).</p><blockquote><p>Retainer and Agile are <strong>frozen project types</strong> as of the 2026-06-06 pivot — new engagements use T&amp;M, Fixed Price, Pro Bono, or Internal. <code>create_retainer_period</code> currently returns <code>❌ Failed: new retainer periods / sprints aren&#39;t currently supported…</code> for every call, regardless of parameters. Existing retainers continue to report correctly via <code>get_retainer_status</code> and <code>get_retainer_periods</code>.</p></blockquote><hr><h2 id="create_sprint" tabindex="-1">create_sprint <a class="header-anchor" href="#create_sprint" aria-label="Permalink to &quot;create_sprint {#create_sprint}&quot;">​</a></h2><p>Create a new sprint under an Agile parent. <strong>Owner only.</strong></p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Writes to</strong>: <code>02. Projects</code></p><p><strong>Parameters:</strong></p><table tabindex="0"><thead><tr><th>Param</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>requesting_user_slack_id</code></td><td>✅</td><td></td></tr><tr><td><code>parent_project_name</code></td><td>✅</td><td>The Agile parent project</td></tr><tr><td><code>contract_value</code></td><td>✅</td><td>Must be asked explicitly — never derived</td></tr><tr><td><code>hours_budget</code></td><td>✅</td><td>Sprint hours estimate</td></tr></tbody></table><p>Sprint number is auto-incremented — do not specify manually.</p><blockquote><p>Retainer and Agile are <strong>frozen project types</strong> as of the 2026-06-06 pivot — new engagements use T&amp;M, Fixed Price, Pro Bono, or Internal. <code>create_sprint</code> currently returns <code>❌ Failed: new retainer periods / sprints aren&#39;t currently supported…</code> for every call, regardless of parameters. Existing Agile projects continue to report correctly via <code>get_agile_summary</code>.</p></blockquote><hr><h2 id="get_agile_summary" tabindex="-1">get_agile_summary <a class="header-anchor" href="#get_agile_summary" aria-label="Permalink to &quot;get_agile_summary {#get_agile_summary}&quot;">​</a></h2><p>All sprints under an Agile project with revenue recognition.</p><p><strong>Reads from</strong>: <code>02. Projects</code>, <code>01. Time Entries</code></p><p><strong>Returns per sprint</strong>: sprint_name, sprint_number, status, contract_value (Owner), hours_budget, hours_logged, recognised_revenue (Owner)</p><hr><h2 id="update_sprint_status" tabindex="-1">update_sprint_status <a class="header-anchor" href="#update_sprint_status" aria-label="Permalink to &quot;update_sprint_status {#update_sprint_status}&quot;">​</a></h2><p>Transition a sprint from <code>planned</code> to <code>active</code>. <strong>Owner only.</strong> No confirmation prompt needed.</p><p><strong>Console-only</strong> — not reachable from Slack; use the web console.</p><p><strong>Updates</strong>: <code>02. Projects</code> col L</p><p><strong>Parameters:</strong> <code>requesting_user_slack_id</code>, <code>sprint_id</code>, <code>new_status</code> (<code>&quot;active&quot;</code>)</p>',177)])])}const u=t(d,[["render",n]]);export{_ as __pageData,u as default};
